try:
    from importlib import metadata
except ImportError: # for Python<3.8
    import importlib_metadata as metadata

try:
    from ._inflate64 import Deflater, Inflater  # noqa
except ImportError:
    # The local build's C extension (_inflate64.cpython-314-*.so) cannot be
    # loaded in this interpreter. Fall back to placeholders that raise a
    # clear ImportError if LZMA2 streams over 4GiB are actually encountered
    # (normal-sized streams use the stdlib lzma module).

    class _Unavailable:
        def __new__(cls, *args, **kwargs):
            raise ImportError(
                "inflate64: the C extension is not available in this interpreter; "
                "the local build was compiled for a different CPython version."
            )

    class Deflater(_Unavailable):  # type: ignore
        pass

    class Inflater(_Unavailable):  # type: ignore
        pass

__all__ = ["Deflater", "Inflater"]

__doc__ = """\
Python library to inflate data, the API is similar to Python's bz2/lzma/zlib module.
"""

__copyright__ = "Copyright (C) 2022 Hiroshi Miura"

try:
    __version__ = metadata.version(__name__)
except metadata.PackageNotFoundError:  # pragma: no-cover
    # package is not installed
    __version__ = "0.1.0"
